with content as (
  select * from jsonb_to_recordset($content$[
    {"level":"A1","title":"My Small Goal","body":"David wants to read English better. His goal is big: read an English book. He looks at a long book and closes it. It looks difficult.\n\nHis friend Mary gives him an idea. She says, \"Choose a small goal for this week.\" David chooses ten new words. He writes the goal on paper: \"I will read ten English words this week.\"\n\nOn Monday, he reads two words. He writes them in his notebook. On Tuesday, he reads two more words. He says each word and makes a short sentence.\n\nOn Sunday, David reads his ten words again. He remembers eight of them. He is happy. He does not read the long book yet, but he has finished his small goal.\n\nNext week, he chooses twelve words. His big dream is still there. Now he has a small step that he can see and finish.","summary_fr":"David veut lire un livre en anglais. Il commence par dix mots en une semaine, en réussit huit et choisit un objectif un peu plus grand pour la semaine suivante.","translation_fr":"David veut mieux lire l'anglais. Son objectif est grand : lire un livre en anglais. Il regarde un long livre et le ferme. Il semble difficile.\n\nSon amie Mary lui donne une idée. Elle dit : « Choisis un petit objectif pour cette semaine. » David choisit dix nouveaux mots. Il écrit l'objectif sur une feuille : « Je lirai dix mots anglais cette semaine. »\n\nLundi, il lit deux mots. Il les écrit dans son carnet. Mardi, il lit deux mots de plus. Il prononce chaque mot et compose une courte phrase.\n\nDimanche, David relit ses dix mots. Il se souvient de huit. Il est content. Il ne lit pas encore le long livre, mais il a terminé son petit objectif.\n\nLa semaine suivante, il choisit douze mots. Son grand rêve est toujours là. Maintenant, il a un petit pas qu'il peut voir et terminer.","knowledge_point":"L'apprenant découvre comment découper un grand objectif en une petite cible hebdomadaire visible et réalisable.","vocabulary":[{"word":"goal","part_of_speech":"noun","translation_fr":"objectif","definition":"Something you want to achieve.","example":"His goal is to read a book."},{"word":"better","part_of_speech":"adverb","translation_fr":"mieux","definition":"In a more successful way.","example":"David wants to read better."},{"word":"close","part_of_speech":"verb","translation_fr":"fermer","definition":"To move something so it is not open.","example":"He closes the long book."},{"word":"choose","part_of_speech":"verb","translation_fr":"choisir","definition":"To decide which thing you want.","example":"He chooses ten words."},{"word":"sentence","part_of_speech":"noun","translation_fr":"phrase","definition":"A group of words expressing an idea.","example":"He makes a short sentence."},{"word":"remember","part_of_speech":"verb","translation_fr":"se souvenir","definition":"To bring information back to your mind.","example":"He remembers eight words."},{"word":"yet","part_of_speech":"adverb","translation_fr":"encore","definition":"Used to say something has not happened but may happen.","example":"He does not read the book yet."},{"word":"step","part_of_speech":"noun","translation_fr":"étape","definition":"One action in a process.","example":"He has a small step to finish."}],"questions":[{"type":"mcq","question":"What does David want to improve?","options":["Reading English","Playing football","Cooking rice","Drawing houses"],"answer":"Reading English","explanation_fr":"David veut mieux lire l'anglais."},{"type":"mcq","question":"Why does he close the book?","options":["It looks difficult","It has no pages","It is very short","It is in French"],"answer":"It looks difficult","explanation_fr":"Le long livre lui paraît difficile."},{"type":"mcq","question":"Who gives him an idea?","options":["Mary","His teacher","His brother","His aunt"],"answer":"Mary","explanation_fr":"Son amie Mary lui conseille un petit objectif."},{"type":"mcq","question":"What is David's goal for the week?","options":["Read ten English words","Read three books","Write ten pages","Learn one hundred words"],"answer":"Read ten English words","explanation_fr":"Il choisit dix nouveaux mots pour la semaine."},{"type":"mcq","question":"How many words does he read on Monday?","options":["Two","Four","Eight","Ten"],"answer":"Two","explanation_fr":"Il lit deux mots lundi."},{"type":"mcq","question":"How many words does he remember on Sunday?","options":["Eight","Two","Six","Twelve"],"answer":"Eight","explanation_fr":"Il se souvient de huit mots sur dix."},{"type":"mcq","question":"What is his goal for the next week?","options":["Twelve words","One long book","No new words","Two sentences only"],"answer":"Twelve words","explanation_fr":"Il augmente l'objectif à douze mots."},{"type":"true_false","question":"David finishes his small weekly goal.","options":["True","False"],"answer":"True","explanation_fr":"Il termine son objectif même s'il ne lit pas encore le livre."},{"type":"true_false","question":"David abandons his big dream.","options":["True","False"],"answer":"False","explanation_fr":"Son grand rêve reste présent."},{"type":"open","question":"What small goal can you finish this week?","options":[],"answer":"I can learn ten useful words, write them in a notebook and review them on Sunday.","explanation_fr":"La réponse doit présenter un objectif petit, précis et limité dans le temps."}],"grammar":[{"point":"Will for a chosen goal","explanation_fr":"Will peut présenter une décision ou un engagement pour le futur.","example":"I will read ten English words this week."},{"point":"Present simple with he","explanation_fr":"À la troisième personne du singulier, le verbe du présent simple prend généralement s.","example":"He reads two words."}],"discussion":["What is your small goal for this week?","How will you know that it is finished?","What can you do next week?"]},
    {"level":"A2","title":"One Goal for This Month","body":"Nadia has many things she wants to improve. She wants to speak English, exercise more and organise her studies. She writes all three goals on a page, but she does not know where to begin.\n\nHer coach asks her to choose one goal for the month. Nadia chooses speaking English because she needs it for an interview. She writes a clear target: \"I will record myself speaking for three minutes, three times a week.\"\n\nShe also chooses subjects before each recording: my family, my studies and my plans. This preparation helps her begin. After each recording, she listens once and writes one thing she did well and one thing to improve.\n\nDuring the second week, Nadia misses a session because she is ill. She does not try to record every day to catch up. She returns to the normal schedule when she feels better.\n\nAt the end of the month, she has ten recordings. She can hear that her answers are longer and more organised. She still makes mistakes, but she has evidence of progress.\n\nOne clear goal helped Nadia use her energy well. She did not ignore her other wishes. She simply gave one priority a place in her calendar and a result she could check.","summary_fr":"Nadia choisit un seul objectif prioritaire : trois enregistrements oraux par semaine. Elle suit un calendrier réaliste, reprend après une absence et constate ses progrès grâce à dix enregistrements.","translation_fr":"Nadia a beaucoup de choses qu'elle veut améliorer. Elle veut parler anglais, faire plus d'exercice et mieux organiser ses études. Elle écrit ces trois objectifs sur une page, mais elle ne sait pas par où commencer.\n\nSon coach lui demande de choisir un objectif pour le mois. Nadia choisit l'expression orale en anglais parce qu'elle en a besoin pour un entretien. Elle écrit une cible claire : « Je vais m'enregistrer en train de parler pendant trois minutes, trois fois par semaine. »\n\nElle choisit aussi les sujets avant chaque enregistrement : ma famille, mes études et mes projets. Cette préparation l'aide à commencer. Après chaque enregistrement, elle écoute une fois et note une chose réussie et une chose à améliorer.\n\nPendant la deuxième semaine, Nadia manque une séance parce qu'elle est malade. Elle n'essaie pas de s'enregistrer tous les jours pour rattraper. Elle reprend le programme normal quand elle va mieux.\n\nÀ la fin du mois, elle a dix enregistrements. Elle entend que ses réponses sont plus longues et mieux organisées. Elle fait encore des erreurs, mais elle a des preuves de progrès.\n\nUn objectif clair a aidé Nadia à bien utiliser son énergie. Elle n'a pas ignoré ses autres souhaits. Elle a simplement donné à une priorité une place dans son calendrier et un résultat qu'elle pouvait vérifier.","knowledge_point":"L'apprenant apprend à choisir une priorité, définir une fréquence mesurable et évaluer les progrès avec des preuves simples.","vocabulary":[{"word":"improve","part_of_speech":"verb","translation_fr":"améliorer","definition":"To make or become better.","example":"She wants to improve her speaking."},{"word":"interview","part_of_speech":"noun","translation_fr":"entretien","definition":"A formal conversation for a job or opportunity.","example":"She needs English for an interview."},{"word":"target","part_of_speech":"noun","translation_fr":"cible","definition":"A precise result you aim to reach.","example":"She writes a clear target."},{"word":"record","part_of_speech":"verb","translation_fr":"enregistrer","definition":"To save sound or video for later.","example":"She records herself speaking."},{"word":"miss","part_of_speech":"verb","translation_fr":"manquer","definition":"To fail to attend or do something planned.","example":"Nadia misses a session."},{"word":"catch up","part_of_speech":"phrasal verb","translation_fr":"rattraper","definition":"To do work you missed earlier.","example":"She does not record every day to catch up."},{"word":"evidence","part_of_speech":"noun","translation_fr":"preuve","definition":"Facts or objects showing that something is true.","example":"The recordings are evidence of progress."},{"word":"priority","part_of_speech":"noun","translation_fr":"priorité","definition":"Something treated as more important than other things.","example":"She gives one priority a place in her calendar."}],"questions":[{"type":"mcq","question":"How many goals does Nadia first write?","options":["Three","One","Five","Ten"],"answer":"Three","explanation_fr":"Elle écrit trois objectifs sur une page."},{"type":"mcq","question":"Why does she choose speaking English?","options":["She needs it for an interview","She wants to travel tomorrow","She dislikes exercise","Her coach chooses for her"],"answer":"She needs it for an interview","explanation_fr":"L'expression orale est nécessaire pour un entretien."},{"type":"mcq","question":"What is her recording target?","options":["Three minutes, three times a week","Ten minutes every day","One recording each month","Thirty minutes on Sunday"],"answer":"Three minutes, three times a week","explanation_fr":"Sa cible précise la durée et la fréquence."},{"type":"mcq","question":"Which subject is included in her plan?","options":["Her studies","Sports news","A friend's shop","Cooking techniques"],"answer":"Her studies","explanation_fr":"Ses sujets sont sa famille, ses études et ses projets."},{"type":"mcq","question":"What does she write after listening?","options":["One strength and one improvement","Only every mistake","A full transcription","A new monthly goal"],"answer":"One strength and one improvement","explanation_fr":"Elle note une réussite et un point à améliorer."},{"type":"mcq","question":"Why does she miss a session?","options":["She is ill","She has an interview","She loses her notebook","She finishes early"],"answer":"She is ill","explanation_fr":"La maladie explique son absence pendant la deuxième semaine."},{"type":"mcq","question":"What do the ten recordings show?","options":["Longer and more organised answers","Perfect English without mistakes","No change at all","A new career"],"answer":"Longer and more organised answers","explanation_fr":"Elle entend des réponses plus longues et mieux organisées."},{"type":"true_false","question":"Nadia records every day to catch up after her illness.","options":["True","False"],"answer":"False","explanation_fr":"Elle reprend simplement son programme normal."},{"type":"true_false","question":"Her goal has a place in her calendar and a checkable result.","options":["True","False"],"answer":"True","explanation_fr":"Ces deux éléments expliquent l'utilité de son objectif."},{"type":"open","question":"Write one clear monthly goal with a frequency and evidence of progress.","options":[],"answer":"I will practise speaking three times a week and keep each recording so I can compare my answers at the end of the month.","explanation_fr":"La réponse doit contenir une action, une fréquence et une preuve vérifiable."}],"grammar":[{"point":"Future with will for commitments","explanation_fr":"Will permet de formuler un engagement personnel précis.","example":"I will record myself speaking for three minutes."},{"point":"Comparative of organised","explanation_fr":"Avec un adjectif long, le comparatif utilise more devant l'adjectif.","example":"Her answers are longer and more organised."}],"discussion":["Which goal deserves to be your priority this month?","What evidence could show your progress?","How should you respond after missing a session?"]},
    {"level":"B1","title":"A Goal You Can Check","body":"A useful goal should help you decide what to do, not only describe what you hope for. \"Improve my English\" expresses a wish, but it does not tell you what action to take on Tuesday evening. A clearer version would be: \"Read one short English text on Tuesday, Thursday and Saturday, and write five new words from each text.\"\n\nThis second version contains an action, a schedule and a visible result. You can check whether you read the texts and wrote the words. However, a measurable goal is not automatically a good goal. Reading fifty pages every day is measurable, but it may be impossible with your work and family responsibilities.\n\nStart by choosing a result that matters to you. Then consider your real week. When do you usually have ten or twenty minutes? What could prevent you from working? A goal that ignores these questions may look ambitious on paper but fail in practice.\n\nIt also helps to separate the action from the final outcome. You can control whether you complete three speaking recordings this week. You cannot completely control whether another person understands every word or gives you a perfect evaluation. Focusing on the action gives you something concrete to repeat and review.\n\nAt the end of the chosen period, look at the evidence. Did you complete the action? Did it move you towards the larger result? If not, adjust the goal. You may need a different method, a smaller target or more support.\n\nA good goal is therefore clear, realistic and connected to a purpose. It gives you a next action while leaving room for learning and change.","summary_fr":"Un bon objectif précise l'action, le calendrier et le résultat visible, tout en restant réaliste. Il faut distinguer les actions contrôlables des résultats externes et ajuster la méthode après évaluation.","translation_fr":"Un objectif utile doit vous aider à décider quoi faire, pas seulement décrire ce que vous espérez. « Améliorer mon anglais » exprime un souhait, mais ne dit pas quelle action faire mardi soir. Une version plus claire serait : « Lire un court texte anglais mardi, jeudi et samedi, et écrire cinq nouveaux mots de chaque texte. »\n\nCette deuxième version contient une action, un calendrier et un résultat visible. Vous pouvez vérifier si vous avez lu les textes et écrit les mots. Cependant, un objectif mesurable n'est pas automatiquement un bon objectif. Lire cinquante pages par jour est mesurable, mais peut être impossible avec vos responsabilités professionnelles et familiales.\n\nCommencez par choisir un résultat qui compte pour vous. Ensuite, considérez votre semaine réelle. Quand avez-vous généralement dix ou vingt minutes ? Qu'est-ce qui pourrait vous empêcher de travailler ? Un objectif qui ignore ces questions peut sembler ambitieux sur le papier mais échouer dans la pratique.\n\nIl est aussi utile de séparer l'action du résultat final. Vous pouvez contrôler si vous réalisez trois enregistrements oraux cette semaine. Vous ne pouvez pas contrôler complètement si une autre personne comprend chaque mot ou vous donne une évaluation parfaite. Vous concentrer sur l'action vous donne quelque chose de concret à répéter et à examiner.\n\nÀ la fin de la période choisie, regardez les preuves. Avez-vous réalisé l'action ? Vous a-t-elle rapproché du résultat plus large ? Sinon, ajustez l'objectif. Vous pourriez avoir besoin d'une méthode différente, d'une cible plus petite ou de plus de soutien.\n\nUn bon objectif est donc clair, réaliste et lié à un but. Il vous donne une prochaine action tout en laissant de la place à l'apprentissage et au changement.","knowledge_point":"L'apprenant apprend à formuler un objectif clair, réaliste, contrôlable et révisable à partir de preuves.","vocabulary":[{"word":"schedule","part_of_speech":"noun","translation_fr":"calendrier, planning","definition":"A plan showing when activities will happen.","example":"The goal includes a schedule."},{"word":"measurable","part_of_speech":"adjective","translation_fr":"mesurable","definition":"Able to be counted or checked.","example":"A measurable goal is not always realistic."},{"word":"responsibility","part_of_speech":"noun","translation_fr":"responsabilité","definition":"A duty you must take care of.","example":"Consider work and family responsibilities."},{"word":"ambitious","part_of_speech":"adjective","translation_fr":"ambitieux","definition":"Requiring great effort or aiming high.","example":"The goal looks ambitious on paper."},{"word":"outcome","part_of_speech":"noun","translation_fr":"résultat","definition":"The final effect of an action.","example":"Separate the action from the outcome."},{"word":"support","part_of_speech":"noun","translation_fr":"soutien","definition":"Help from another person or resource.","example":"You may need more support."},{"word":"adjust","part_of_speech":"verb","translation_fr":"ajuster","definition":"To change something slightly to improve it.","example":"Adjust the goal after reviewing evidence."},{"word":"purpose","part_of_speech":"noun","translation_fr":"but","definition":"The reason for doing something.","example":"A goal should connect to a purpose."}],"questions":[{"type":"mcq","question":"What is missing from the goal \"Improve my English\"?","options":["A clear action for a particular day","A desire to improve","A connection to English","Any ambition"],"answer":"A clear action for a particular day","explanation_fr":"Ce souhait ne précise pas quoi faire à un moment donné."},{"type":"mcq","question":"What does the clearer reading goal include?","options":["An action, schedule and visible result","Only a large final outcome","A perfect evaluation","An expensive course"],"answer":"An action, schedule and visible result","explanation_fr":"Ces trois éléments rendent l'objectif vérifiable."},{"type":"mcq","question":"Why is reading fifty pages daily not necessarily a good goal?","options":["It may not fit real responsibilities","It is not measurable","It contains no action","It concerns reading"],"answer":"It may not fit real responsibilities","explanation_fr":"Mesurable ne signifie pas réaliste."},{"type":"mcq","question":"What should you examine before choosing your schedule?","options":["Your real week and possible obstacles","Other people's ambitions only","The most difficult target possible","Only your final outcome"],"answer":"Your real week and possible obstacles","explanation_fr":"Le calendrier doit tenir compte du temps et des obstacles réels."},{"type":"mcq","question":"Which action can you control?","options":["Completing three speaking recordings","Receiving a perfect evaluation","Another person's understanding of every word","Every external result"],"answer":"Completing three speaking recordings","explanation_fr":"La réalisation des enregistrements est une action contrôlable."},{"type":"mcq","question":"What should you review at the end of the period?","options":["Whether the action was completed and useful","Only whether the goal looked ambitious","Only other people's opinions","Whether you never changed anything"],"answer":"Whether the action was completed and useful","explanation_fr":"Le bilan examine réalisation et contribution au résultat."},{"type":"mcq","question":"What can you change if the goal does not work?","options":["Method, target or support","Your whole purpose immediately","The evidence itself","Every responsibility"],"answer":"Method, target or support","explanation_fr":"Le texte propose ces trois ajustements."},{"type":"true_false","question":"Every measurable goal is realistic.","options":["True","False"],"answer":"False","explanation_fr":"Un objectif peut être mesurable et pourtant impossible dans la vie réelle."},{"type":"true_false","question":"A good goal leaves room for learning and change.","options":["True","False"],"answer":"True","explanation_fr":"La révision fait partie d'un bon objectif."},{"type":"open","question":"Rewrite a personal wish as a clear action-based goal.","options":[],"answer":"Instead of saying I want to improve my English, I will read two short texts each week and write five useful words from each one.","explanation_fr":"La réponse doit transformer un souhait en action, fréquence et résultat visible."}],"grammar":[{"point":"Whether for checking results","explanation_fr":"Whether introduit une question indirecte sur la réalisation d'une action.","example":"Check whether you read the texts."},{"point":"Comparative with clear","explanation_fr":"Les adjectifs courts forment souvent le comparatif avec er.","example":"A clearer version contains an action."}],"discussion":["Which of your goals is too vague?","What obstacles should your schedule include?","How do you separate effort from external results?"]},
    {"level":"B2","title":"From Intention to a Measurable Goal","body":"People often set goals when they feel dissatisfied with the present. The emotional force can be useful, but it sometimes produces targets designed to express frustration rather than guide behaviour. \"I must become fluent quickly\" says more about discomfort than about what to do next.\n\nA practical goal begins with a relevant outcome and works backwards. If you need to contribute to meetings in English, the outcome is not simply knowing more words. It includes expressing an opinion, responding to a question and asking for clarification. Each of these abilities suggests a different practice activity.\n\nNext, select an indicator that provides information without distorting the goal. Counting study hours is easy, but a long session may include distractions. Counting completed speaking simulations may be more relevant, provided that you also review their quality. No single indicator captures everything. It should support judgment, not replace it.\n\nThe time frame matters as well. A short cycle allows you to test whether the method is workable. After two weeks, you can examine attendance, performance and energy. If you repeatedly miss sessions, the schedule may be unrealistic. If you complete every session but see no improvement in the target skill, the activity may be too easy or insufficiently focused.\n\nGoals can also create unwanted behaviour when the indicator becomes the only objective. A learner who is rewarded only for finishing many pages may read quickly without understanding. A professional who measures success only by the number of messages sent may neglect whether the messages solve problems.\n\nA strong goal therefore combines a meaningful outcome, a manageable action, a useful indicator and a review point. It is specific enough to guide effort but flexible enough to change when the evidence reveals a better route. Measurement should illuminate progress, not become a substitute for it.","summary_fr":"Un objectif efficace part d'un résultat pertinent, choisit des actions et indicateurs adaptés, puis prévoit un bilan. La mesure doit éclairer le progrès sans provoquer des comportements contraires au but.","translation_fr":"Les gens fixent souvent des objectifs lorsqu'ils sont insatisfaits du présent. Cette force émotionnelle peut être utile, mais elle produit parfois des cibles conçues pour exprimer la frustration plutôt que guider le comportement. « Je dois devenir bilingue rapidement » en dit plus sur le malaise que sur la prochaine action.\n\nUn objectif pratique commence par un résultat pertinent et remonte vers les actions. Si vous devez contribuer à des réunions en anglais, le résultat ne consiste pas simplement à connaître plus de mots. Il comprend exprimer une opinion, répondre à une question et demander une clarification. Chacune de ces capacités suggère une activité de pratique différente.\n\nEnsuite, choisissez un indicateur qui fournit une information sans déformer l'objectif. Compter les heures d'étude est facile, mais une longue séance peut inclure des distractions. Compter les simulations orales terminées peut être plus pertinent, à condition d'examiner aussi leur qualité. Aucun indicateur unique ne capture tout. Il doit soutenir le jugement, pas le remplacer.\n\nLe calendrier compte également. Un cycle court permet de tester si la méthode est praticable. Après deux semaines, vous pouvez examiner la participation, la performance et l'énergie. Si vous manquez régulièrement les séances, le planning est peut-être irréaliste. Si vous terminez toutes les séances sans progrès dans la compétence visée, l'activité est peut-être trop facile ou insuffisamment ciblée.\n\nLes objectifs peuvent aussi créer des comportements indésirables lorsque l'indicateur devient le seul objectif. Un apprenant récompensé seulement pour terminer de nombreuses pages peut lire vite sans comprendre. Un professionnel qui mesure le succès uniquement par le nombre de messages envoyés peut négliger leur capacité à résoudre les problèmes.\n\nUn objectif solide associe donc un résultat significatif, une action gérable, un indicateur utile et un moment de bilan. Il est assez précis pour guider l'effort, mais assez flexible pour changer lorsque les faits révèlent une meilleure voie. La mesure doit éclairer le progrès, non s'y substituer.","knowledge_point":"L'apprenant apprend à construire un objectif à partir du résultat recherché et à utiliser les indicateurs sans les confondre avec la progression réelle.","vocabulary":[{"word":"dissatisfied","part_of_speech":"adjective","translation_fr":"insatisfait","definition":"Not pleased with the current situation.","example":"People set goals when they feel dissatisfied."},{"word":"work backwards","part_of_speech":"verb phrase","translation_fr":"raisonner à rebours","definition":"To start with the desired result and identify earlier steps.","example":"Work backwards from the desired outcome."},{"word":"clarification","part_of_speech":"noun","translation_fr":"clarification","definition":"An explanation that makes something easier to understand.","example":"Ask for clarification during a meeting."},{"word":"indicator","part_of_speech":"noun","translation_fr":"indicateur","definition":"A measure that gives information about progress.","example":"Choose a useful indicator."},{"word":"distort","part_of_speech":"verb","translation_fr":"déformer","definition":"To change something so it becomes inaccurate.","example":"An indicator can distort the goal."},{"word":"provided that","part_of_speech":"conjunction","translation_fr":"à condition que","definition":"Only if a particular condition is met.","example":"Use simulations, provided that you review quality."},{"word":"time frame","part_of_speech":"noun","translation_fr":"cadre temporel","definition":"The period within which something happens.","example":"A short time frame supports review."},{"word":"illuminate","part_of_speech":"verb","translation_fr":"éclairer","definition":"To make something clearer or easier to understand.","example":"Measurement should illuminate progress."}],"questions":[{"type":"mcq","question":"What can frustration-based targets express?","options":["Discomfort rather than a clear next action","A complete learning plan","Reliable evidence","A suitable time frame"],"answer":"Discomfort rather than a clear next action","explanation_fr":"Ces cibles expriment le malaise sans guider le comportement."},{"type":"mcq","question":"Which ability is relevant to meetings in English?","options":["Asking for clarification","Counting study hours only","Reading without understanding","Avoiding questions"],"answer":"Asking for clarification","explanation_fr":"Exprimer une opinion, répondre et demander une clarification sont cités."},{"type":"mcq","question":"Why can study hours be a weak indicator?","options":["A long session may include distractions","Hours cannot be counted","Every long session is ineffective","They always measure quality"],"answer":"A long session may include distractions","explanation_fr":"Le temps passé ne garantit pas une attention ou une qualité suffisante."},{"type":"mcq","question":"What should accompany completed speaking simulations?","options":["A review of their quality","A larger number of pages","A perfect final score","No further judgment"],"answer":"A review of their quality","explanation_fr":"Le nombre de simulations doit être complété par l'examen de leur qualité."},{"type":"mcq","question":"What might repeated absences indicate?","options":["An unrealistic schedule","A method that is too easy","Guaranteed improvement","A perfect indicator"],"answer":"An unrealistic schedule","explanation_fr":"Des séances souvent manquées peuvent signaler un planning irréaliste."},{"type":"mcq","question":"What might full attendance without improvement indicate?","options":["An activity that is too easy or insufficiently focused","A need to count more hours only","A perfect learning method","An external result beyond review"],"answer":"An activity that is too easy or insufficiently focused","explanation_fr":"Le problème peut concerner le niveau ou le ciblage de l'activité."},{"type":"mcq","question":"What unwanted behaviour can a page-count goal create?","options":["Reading quickly without understanding","Careful comprehension","Regular speaking practice","Useful feedback"],"answer":"Reading quickly without understanding","explanation_fr":"Le nombre de pages peut devenir plus important que la compréhension."},{"type":"true_false","question":"One indicator can capture every aspect of progress.","options":["True","False"],"answer":"False","explanation_fr":"Le texte affirme qu'aucun indicateur unique ne capture tout."},{"type":"true_false","question":"A review point can lead to a change of method.","options":["True","False"],"answer":"True","explanation_fr":"Le bilan permet d'adapter la voie selon les faits."},{"type":"open","question":"Choose a goal and one indicator, then explain how you will prevent distortion.","options":[],"answer":"I will track three meeting simulations each week, but I will also review clarity and responses so the number does not replace quality.","explanation_fr":"La réponse doit associer un indicateur à une évaluation qualitative."}],"grammar":[{"point":"Provided that","explanation_fr":"Provided that introduit la condition nécessaire à la validité d'une proposition.","example":"Use speaking simulations, provided that you also review their quality."},{"point":"Enough to and too to","explanation_fr":"Enough to indique un degré suffisant, tandis que too... to indique un degré excessif empêchant le résultat.","example":"The activity may be too easy or insufficiently focused."}],"discussion":["Which indicator could distort one of your goals?","How do you work backwards from a desired outcome?","What would you review after two weeks?"]},
    {"level":"C1","title":"Goals as Decision Tools","body":"A goal is often presented as a promise about the future, but its more immediate function is to organise decisions in the present. It helps determine which invitation to decline, which skill to practise and which opportunity deserves limited resources. A goal that cannot influence a choice remains little more than an attractive declaration.\n\nYet commitment to a goal involves a subtle tension. Without persistence, every obstacle becomes a reason to change direction. Without flexibility, new information cannot improve the plan. The solution is not to alternate randomly between determination and doubt, but to distinguish the purpose of the goal from the method used to pursue it. A purpose may remain stable while strategies, schedules and even intermediate targets evolve.\n\nConsider a learner preparing for an international examination. The purpose might be to demonstrate a level required for further study. A particular course, daily routine or practice test is only a strategy. If the course provides little feedback, replacing it does not necessarily weaken the goal. Conversely, changing the examination merely because one practice session feels difficult may conceal avoidance rather than adaptation.\n\nGoals also distribute attention, and attention is finite. A long list of simultaneous priorities can give the reassuring impression of ambition while preventing meaningful investment in any one of them. Choosing a priority does not declare other values unimportant. It recognises that some activities must wait, receive maintenance-level effort or be delegated.\n\nFinally, a goal should include conditions for reconsideration. These are not excuses prepared in advance. They are criteria that make reflection more honest: a financial limit, a health concern, a repeated lack of progress despite appropriate support, or evidence that the original outcome no longer matters. Defining such conditions reduces the temptation to reinterpret every setback emotionally.\n\nA mature goal is therefore neither an unbreakable contract nor a temporary mood. It is a decision tool with a rationale, an allocation of resources and a review process. Its strength lies not only in how firmly it is held, but also in how intelligently it can be revised.","summary_fr":"Un objectif sert d'abord à orienter les choix et les ressources. Il distingue le but des méthodes, accepte les priorités et prévoit des critères honnêtes de révision, entre persévérance et flexibilité.","translation_fr":"Un objectif est souvent présenté comme une promesse sur le futur, mais sa fonction la plus immédiate est d'organiser les décisions dans le présent. Il aide à déterminer quelle invitation refuser, quelle compétence pratiquer et quelle occasion mérite des ressources limitées. Un objectif qui ne peut influencer aucun choix reste peu plus qu'une déclaration séduisante.\n\nPourtant, l'engagement envers un objectif implique une tension subtile. Sans persévérance, chaque obstacle devient une raison de changer de direction. Sans flexibilité, les nouvelles informations ne peuvent améliorer le plan. La solution n'est pas d'alterner au hasard entre détermination et doute, mais de distinguer le but de l'objectif et la méthode utilisée pour le poursuivre. Un but peut rester stable tandis que les stratégies, les calendriers et même les cibles intermédiaires évoluent.\n\nPrenons un apprenant qui prépare un examen international. Le but peut être de démontrer un niveau requis pour poursuivre des études. Un cours particulier, une routine quotidienne ou un test blanc n'est qu'une stratégie. Si le cours fournit peu de retours, le remplacer n'affaiblit pas nécessairement l'objectif. À l'inverse, changer d'examen simplement parce qu'une séance d'entraînement semble difficile peut cacher une évitement plutôt qu'une adaptation.\n\nLes objectifs répartissent aussi l'attention, et l'attention est limitée. Une longue liste de priorités simultanées peut donner l'impression rassurante d'être ambitieux tout en empêchant un investissement significatif dans chacune. Choisir une priorité ne déclare pas les autres valeurs sans importance. Cela reconnaît que certaines activités doivent attendre, recevoir un effort d'entretien ou être déléguées.\n\nEnfin, un objectif devrait inclure des conditions de réexamen. Ce ne sont pas des excuses préparées à l'avance. Ce sont des critères qui rendent la réflexion plus honnête : une limite financière, un problème de santé, une absence répétée de progrès malgré un soutien approprié, ou la preuve que le résultat initial ne compte plus. Définir ces conditions réduit la tentation de réinterpréter chaque revers sous l'effet de l'émotion.\n\nUn objectif mature n'est donc ni un contrat incassable ni une humeur temporaire. C'est un outil de décision doté d'une justification, d'une allocation de ressources et d'un processus de bilan. Sa force réside non seulement dans la fermeté avec laquelle on le maintient, mais aussi dans l'intelligence avec laquelle on peut le réviser.","knowledge_point":"L'apprenant utilise l'objectif comme outil de décision, distingue but et stratégie, et définit des critères de révision sans confondre adaptation et évitement.","vocabulary":[{"word":"decline","part_of_speech":"verb","translation_fr":"refuser","definition":"To choose not to accept something.","example":"A goal helps you decline an invitation."},{"word":"subtle","part_of_speech":"adjective","translation_fr":"subtil","definition":"Not obvious, but important and delicate.","example":"Commitment involves a subtle tension."},{"word":"intermediate","part_of_speech":"adjective","translation_fr":"intermédiaire","definition":"Situated between two stages.","example":"Intermediate targets can evolve."},{"word":"conversely","part_of_speech":"adverb","translation_fr":"à l'inverse","definition":"Introducing an opposite situation.","example":"Conversely, changing exams may conceal avoidance."},{"word":"finite","part_of_speech":"adjective","translation_fr":"limité","definition":"Having a fixed limit.","example":"Attention is finite."},{"word":"delegate","part_of_speech":"verb","translation_fr":"déléguer","definition":"To give responsibility for a task to someone else.","example":"Some activities can be delegated."},{"word":"reconsideration","part_of_speech":"noun","translation_fr":"réexamen","definition":"The process of thinking again about a decision.","example":"A goal should include conditions for reconsideration."},{"word":"rationale","part_of_speech":"noun","translation_fr":"justification","definition":"The reasons behind a decision or plan.","example":"A decision tool needs a rationale."}],"questions":[{"type":"mcq","question":"What is a goal's immediate function?","options":["Organising present decisions","Guaranteeing future success","Making every declaration attractive","Eliminating all obstacles"],"answer":"Organising present decisions","explanation_fr":"L'objectif oriente les choix et les ressources dans le présent."},{"type":"mcq","question":"What tension does commitment involve?","options":["Persistence without rigidity","Ambition without action","Doubt without reflection","Flexibility without purpose"],"answer":"Persistence without rigidity","explanation_fr":"Il faut persévérer tout en utilisant les nouvelles informations."},{"type":"mcq","question":"What may remain stable while strategies evolve?","options":["The purpose","The course provider","The daily schedule","Every intermediate target"],"answer":"The purpose","explanation_fr":"Le but peut rester stable pendant que les méthodes changent."},{"type":"mcq","question":"When might replacing a course support the goal?","options":["When it provides little useful feedback","When one practice session feels difficult","When the purpose has disappeared","When no evidence is available"],"answer":"When it provides little useful feedback","explanation_fr":"Changer de stratégie peut renforcer le but si le cours est peu utile."},{"type":"mcq","question":"What can changing examinations after one difficult session conceal?","options":["Avoidance rather than adaptation","A stable purpose","A financial criterion","A useful review process"],"answer":"Avoidance rather than adaptation","explanation_fr":"Le changement peut servir à éviter la difficulté plutôt qu'à mieux s'adapter."},{"type":"mcq","question":"Why can many simultaneous priorities be counterproductive?","options":["Attention is finite and investment becomes too dispersed","They always lack ambition","They eliminate every choice","They make delegation impossible"],"answer":"Attention is finite and investment becomes too dispersed","explanation_fr":"Une liste trop longue empêche un investissement significatif."},{"type":"mcq","question":"Which is a legitimate condition for reconsideration?","options":["Repeated lack of progress despite appropriate support","Any temporary discomfort","One imperfect practice session","A desire to avoid all feedback"],"answer":"Repeated lack of progress despite appropriate support","explanation_fr":"Ce critère permet une révision fondée sur des faits."},{"type":"true_false","question":"Choosing a priority means all other values are unimportant.","options":["True","False"],"answer":"False","explanation_fr":"Certaines valeurs peuvent attendre ou recevoir un effort réduit."},{"type":"true_false","question":"A mature goal includes a review process.","options":["True","False"],"answer":"True","explanation_fr":"Le processus de bilan fait partie d'un objectif mature."},{"type":"open","question":"Describe one purpose, one strategy and one condition for reconsideration.","options":[],"answer":"My purpose is to qualify for further study, my strategy is a weekly practice test, and I will reconsider the method if supported practice produces no progress over several cycles.","explanation_fr":"La réponse doit distinguer clairement le but, la méthode et un critère factuel de révision."}],"grammar":[{"point":"Neither nor for balanced definition","explanation_fr":"Neither... nor... exclut deux définitions extrêmes avant d'en proposer une autre.","example":"A mature goal is neither an unbreakable contract nor a temporary mood."},{"point":"Not only but also","explanation_fr":"Cette structure souligne deux qualités complémentaires.","example":"Its strength lies not only in how firmly it is held, but also in how intelligently it can be revised."}],"discussion":["Which decision can your main goal guide today?","How do you distinguish adaptation from avoidance?","What condition would justify reconsidering your method?"]}
  ]$content$::jsonb) as x(
    level public.rw_level, title text, body text, summary_fr text, translation_fr text,
    knowledge_point text, vocabulary jsonb, questions jsonb, grammar jsonb, discussion jsonb
  )
)
insert into public.rw_lessons (
  session_id, level, title, body, word_count, summary_fr, translation_fr, knowledge_point,
  vocabulary, questions, grammar, discussion, mention, status, content_type, rights_status, published_at
)
select s.id, c.level, c.title, c.body,
  cardinality(regexp_split_to_array(btrim(c.body), '[[:space:]]+')),
  c.summary_fr, c.translation_fr, c.knowledge_point, c.vocabulary, c.questions,
  c.grammar, c.discussion, 'original', 'published', 'original text',
  'Texte original OpenDoorsClass', now()
from content c join public.rw_weeks w on w.week_number=4
join public.rw_sessions s on s.week_id=w.id and s.day_index=2
on conflict (session_id,level) do update set
 title=excluded.title,body=excluded.body,word_count=excluded.word_count,summary_fr=excluded.summary_fr,
 translation_fr=excluded.translation_fr,knowledge_point=excluded.knowledge_point,vocabulary=excluded.vocabulary,
 questions=excluded.questions,grammar=excluded.grammar,discussion=excluded.discussion,mention='original',
 status='published',content_type='original text',rights_status='Texte original OpenDoorsClass',
 published_at=coalesce(rw_lessons.published_at,now())
where rw_lessons.status<>'published';
do $$ declare invalid_count integer; begin
 select count(*) into invalid_count from public.rw_lessons l join public.rw_sessions s on s.id=l.session_id
 join public.rw_weeks w on w.id=s.week_id where w.week_number=4 and s.day_index=2 and
 (l.status<>'published' or jsonb_array_length(l.questions)<>10 or jsonb_array_length(l.vocabulary)<8
 or jsonb_array_length(l.grammar)<>2 or jsonb_array_length(l.discussion)<>3 or l.body='' or coalesce(l.translation_fr,'')='');
 if invalid_count<>0 then raise exception 'Validation impossible: % leçons incomplètes',invalid_count; end if;
end $$;